const row = $input.first().json;
const data = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;

const unreturned = data.unreturned || [];
const tomorrowPrep = data.tomorrow_prep || [];
const completed = Number(data.completed_today || 0);
const total = Number(data.total_today || 0);

// If nothing to report, send a short summary
if (unreturned.length === 0 && tomorrowPrep.length === 0) {
  const msg = `\ud83c\udf19 <b>Vakaro ataskaita</b>\n\n` +
    `\u2705 Visos \u012frangos gr\u0105\u017eintos (${completed}/${total} atlikta)\n` +
    `\ud83d\udcc5 Rytoj u\u017esakym\u0173 n\u0117ra\n\n` +
    `Geros nakties! \ud83d\ude34`;
  return [{ json: { message: msg } }];
}

let msg = `\ud83c\udf19 <b>Vakaro ataskaita</b>\n`;
msg += `\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n`;

// Day summary
msg += `\ud83d\udcca \u0160iandien: ${completed}/${total} u\u017esakym\u0173 atlikta\n\n`;

// Unreturned equipment alert
if (unreturned.length > 0) {
  msg += `\ud83d\udea8 <b>NEGR\u0104\u017dINTA \u012eRANGA (${unreturned.length}):</b>\n`;
  unreturned.forEach(b => {
    const equip = Array.isArray(b.equipment) ? b.equipment.map(e => `${e.icon||'\ud83c\udfaa'} ${e.name}`).join(', ') : '';
    msg += `\n  \ud83d\ude9b <b>#${b.id}</b> \u2014 tur\u0117jo b\u016bti iki ${(b.pickup_time||'?').substring(0,5)}`;
    msg += `\n   \ud83d\udccd ${b.delivery_address}, ${b.city}`;
    msg += `\n   \ud83d\udc64 ${b.customer_name} \ud83d\udcde ${b.customer_phone}`;
    msg += `\n   ${equip}`;
    msg += `\n   \u27a1\ufe0f /returned ${b.id}\n`;
  });
  msg += '\n';
}

// Tomorrow preparation
if (tomorrowPrep.length > 0) {
  msg += `\ud83d\udcc6 <b>RYTOJAUS PARUOŠIMAS (${tomorrowPrep.length} u\u017es.):</b>\n`;
  tomorrowPrep.forEach(b => {
    const equip = Array.isArray(b.equipment) ? b.equipment : [];
    const needsClean = equip.filter(e => e.status === 'Needs Cleaning');
    const depositWarn = !b.deposit_paid ? ` \ud83d\udd34 Avansas \u20ac${b.deposit_amount} NEMOK\u0116TAS!` : '';

    msg += `\n  \ud83d\udfe1 <b>#${b.id}</b> ${(b.event_time||'?').substring(0,5)} \u2192 ${(b.pickup_time||'?').substring(0,5)}`;
    msg += `\n   \ud83d\udccd ${b.delivery_address}, ${b.city}`;
    msg += `\n   \ud83d\udc64 ${b.customer_name} \ud83d\udcde ${b.customer_phone}${depositWarn}`;
    msg += `\n   \u2611\ufe0f `;
    equip.forEach(e => { msg += `${e.icon||'\ud83c\udfaa'} ${e.name} `; });
    if (needsClean.length > 0) {
      msg += `\n   \u26a0\ufe0f REIKIA I\u0160VALYTI: ${needsClean.map(e => `${e.icon} ${e.name} (/clean ${e.id})`).join(', ')}`;
    }
    msg += '\n';
  });
}

return [{ json: { message: msg } }];
